import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import {chromium} from '@playwright/test';
import {createGameServer} from '../server.mjs';
import {defaults,clone,contractType} from '../src/config.js';
const dir='evidence/audit-20261026',out={created:new Date().toISOString(),checks:[],skills:[],errors:[],networkErrors:[],screenshots:[]};
const game=createGameServer({dataDir:fs.mkdtempSync(path.join(os.tmpdir(),'kc5-audit-'))});game.room.paused=true;
await new Promise((resolve,reject)=>{game.server.once('error',reject);game.server.listen(0,'127.0.0.1',resolve);});
const base=`http://127.0.0.1:${game.server.address().port}`,room=game.room,s=room.sim;out.base=base;out.dataDir=game.accounts.file;
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});const contexts=[],pages=[],ids=[0,3,4,5,2],actors=[];
async function shot(page,name){const file=`${dir}/${name}.png`;await page.screenshot({path:file,fullPage:false});out.screenshots.push(file);}
async function check(name,fn){try{const evidence=structuredClone(await fn());out.checks.push({name,status:'PASS',evidence});}catch(e){out.checks.push({name,status:'FAIL',error:e.message,stack:e.stack});}}
async function sync(){room.sequence++;room.broadcast();await Promise.all(pages.map(p=>p.waitForFunction(seq=>window.__game?.sim.sequence>=seq,room.sequence)));}
function advance(seconds){const end=s.time+seconds;while(s.time<end-1e-8)s.tick(Math.min(.05,end-s.time));}
async function clickUnit(page,id,touch=false){await page.evaluate(id=>__game.renderer.focusUnit(id),id);await page.waitForTimeout(360);const point=await page.evaluate(id=>{const p=__game.renderer.screenPoint(__game.sim.get(id)),r=__game.renderer.game.canvas.getBoundingClientRect(),cfg=__game.renderer.game.config;return {x:r.left+p.x/Number(cfg.width)*r.width,y:r.top+(p.y-27)/Number(cfg.height)*r.height};},id);if(touch)await page.touchscreen.tap(point.x,point.y);else await page.mouse.click(point.x,point.y);return point;}
async function register(classId){const context=await browser.newContext({viewport:{width:1440,height:1200}}),page=await context.newPage();contexts.push(context);pages.push(page);page.on('pageerror',e=>out.errors.push({classId,message:e.message}));page.on('response',r=>{if(r.status()>=400)out.networkErrors.push({classId,url:r.url(),status:r.status()});});await page.goto(base);await page.locator('#accountName').fill(`检测${classId}-${Date.now()}`);await page.locator('#accountPassword').fill('isolated-audit-only');await page.locator(`[name="side"][value="${classId===3?1:0}"]`).check();await page.locator('#authSubmit').click();await page.waitForFunction(()=>window.__game?.sim.player?.accountId&&__game.renderer.getCamera());const account=game.accounts.rows.at(-1),p=room.player(account);actors.push({classId,context,page,account,p});return actors.at(-1);}
function prepare(actor,skill){
 s.units=s.units.filter(u=>u.hero&&actors.some(a=>a.p.heroId===u.id));s.fields=[];s.jobs=[];s.projectiles=[];s.animations=[];s.effects=[];s.skillValues=[];s.waveAt=1e9;
 for(const t of s.towers){t.x=100;t.cd=1e9;}
 for(const a of actors){const u=s.hero(a.p);Object.assign(u,{x:a.classId===actor.classId?0:2,y:a.p.side===actor.p.side?0:3,hp:u.maxHp*.4,cd:1e9,speed:0,castUntil:0,channelUntil:0,stunUntil:0,dash:null,guards:[],debuffs:{},damageStore:null,shield:0,heat:0,heatUntil:0,lordUlt:null,immuneUntil:0});a.p.cd=[0,0,0,0];a.p.stamina=97;}
 const h=s.hero(actor.p),opposite=actors.find(a=>a.p.side!==actor.p.side),enemy=s.hero(opposite.p);enemy.x=0;enemy.y=3;enemy.maxHp=enemy.hp=1e7;
 const friends=[];for(let i=0;i<4;i++){const u=s.spawn(actor.p.side,'melee',i,4,(i-1.5)*1.5);Object.assign(u,{y:1,hp:1000,maxHp:10000,speed:0,cd:1e9});friends.push(u);}
 for(let i=0;i<3;i++){const u=s.spawn(1-actor.p.side,'melee',i,3,i-1);Object.assign(u,{y:3,hp:1e7,maxHp:1e7,speed:0,cd:1e9});}
 enemy.targetId=friends[0].id;h.targetId=enemy.id;if(actor.classId===4){h.heat=5;h.heatUntil=s.time+15;}
 if(actor.classId===5&&skill===2)s.debuff(friends[0],enemy,'attackDown',.2,10);
 return {h,enemy,friends};
}
try{
 for(const id of ids)await register(id);
 await check('5 accounts, 2 camps, one match, zero default bots, host controls separate',async()=>{const states=await Promise.all(pages.map(p=>p.evaluate(()=>({match:__game.sim.matchId,playerId:__game.sim.player.id,bots:__game.sim.players.filter(p=>p.bot&&!p.retired).length,side:__game.sim.player.side,hidden:document.querySelector('#skills').hidden,controlsInside:!!document.querySelector('.game #hostControls')}))));assert.equal(new Set(states.map(x=>x.match)).size,1);assert.equal(new Set(states.map(x=>x.playerId)).size,5);assert.ok(states.every(x=>x.bots===0&&x.hidden&&!x.controlsInside));return states;});
 for(const actor of actors)await check(`class${actor.classId} real canvas selection and contract confirmation`,async()=>{const u=s.units.find(u=>!u.hero&&u.side===actor.p.side&&u.type===contractType(actor.classId));const before=actor.p.stamina;const point=await clickUnit(actor.page,u.id);await actor.page.locator('#contractPopover').waitFor({state:'visible'});const selected=await actor.page.evaluate(()=>__game.selection.id);assert.equal(selected,u.id);assert.equal(s.hero(actor.p),undefined);if([4,5].includes(actor.classId))await actor.page.locator(`[data-contract-role="${actor.classId}"]`).click();await shot(actor.page,`contract-${actor.classId}`);await actor.page.locator('#confirmContract').click();await actor.page.waitForFunction(id=>__game.sim.hero()?.classId===id,actor.classId);assert.equal(actor.p.stamina,before-3);return {selected,point,heroId:actor.p.heroId};});
 assert.ok(actors.every(a=>s.hero(a.p)),'Every browser must have completed real contract');
 await check('unlock and skill points via UI, classes 1/2/4/6 gates',async()=>{const a=actors[0];const start=await a.page.locator('[data-cast]').evaluateAll(es=>es.map(e=>({label:e.getAttribute('aria-label'),state:e.dataset.state})));assert.equal(start[1].state,'locked');for(let i=0;i<5;i++){await a.page.locator('#level').click();await a.page.waitForFunction(l=>__game.sim.player.level===l,i+2);}for(const actor of actors.slice(1)){actor.p.level=6;actor.p.points=5;}await sync();for(const actor of actors){for(let i=1;i<4;i++){await actor.page.locator(`[data-up="${i}"]`).click();await actor.page.waitForFunction(i=>__game.sim.player.builds[__game.sim.player.classId][i]===1,i);}assert.deepEqual(actor.p.builds[actor.classId],[1,1,1,1]);}await shot(a.page,'upgraded-hud');return {start,builds:actors.map(a=>({classId:a.classId,build:a.p.builds[a.classId]}))};});
 for(const actor of actors)for(let skill=0;skill<4;skill++)await check(`class${actor.classId} skill${skill+1} actual button/SSE/effect`,async()=>{
  const {h,enemy}=prepare(actor,skill);await sync();await actor.page.locator('#locate').click();await actor.page.waitForTimeout(300);await actor.page.waitForFunction(i=>__game.sim.castPlan(i).ok,skill);const before={stamina:actor.p.stamina,hp:enemy.hp,heroHp:h.hp,casts:s.metrics.casts};
  await actor.page.locator(`[data-cast="${skill}"]`).click();await actor.page.waitForFunction(i=>__game.sim.player.cd[i]>__game.sim.time,skill);assert.equal(actor.p.stamina,before.stamina-s.config.heroes[actor.classId].skills[skill].cost);advance(.4);await sync();await actor.page.waitForTimeout(100);await shot(actor.page,`skill-${actor.classId}-${skill+1}-release`);advance(actor.classId===2&&skill===2?3.1:actor.classId===3&&skill===1?1.2:1);await sync();
  const snapshots=await Promise.all(pages.map(p=>p.evaluate(()=>({sequence:__game.sim.sequence,units:__game.sim.units.map(u=>[u.id,u.hp,u.shield||0]),casts:__game.sim.metrics.casts}))));assert.ok(snapshots.every(v=>JSON.stringify(v.units)===JSON.stringify(snapshots[0].units)));assert.equal(s.metrics.casts,before.casts+1);assert.ok(s.skillValues.every(v=>v.spent<=v.limit+1e-6));
  const evidence={classId:actor.classId,skill:skill+1,before,after:{stamina:actor.p.stamina,targetHp:enemy.hp,heroHp:h.hp,shield:h.shield,energy:h.energy,heat:h.heat,damageStore:h.damageStore,fields:s.fields.map(f=>({kind:f.kind,remaining:f.remaining,host:f.host})),debuffs:enemy.debuffs},value:s.skillValues.at(-1),sequences:snapshots.map(v=>v.sequence)};out.skills.push(evidence);return evidence;
 });
 await check('real stored damage to self shield snapshot and continued SSE, all 5 clients',async()=>{const actor=actors[0],{h,enemy}=prepare(actor,3);await sync();await actor.page.locator('[data-cast="3"]').click();await actor.page.waitForFunction(()=>__game.sim.player.cd[3]>__game.sim.time);advance(.4);s.damage(enemy,h,500);advance(5);await sync();const payload=JSON.stringify(room.snapshot());assert.equal(h.shield,500);await shot(actor.page,'self-shield-sse');const res=await actor.page.request.get(base+'/api/state');assert.equal(res.status(),200);await actor.page.reload();await actor.page.waitForFunction(()=>__game.sim.hero()?.shield===500);advance(.3);await sync();return {snapshotBytes:payload.length,shieldSourceId:h.shieldSource.id,sequence:room.sequence,connected:room.clients.size};});
 await check('refresh/offline/online keeps player hero class and camp',async()=>{const a=actors[1],before={id:a.p.id,heroId:a.p.heroId,side:a.p.side};await a.context.setOffline(true);await a.page.locator('#connection').filter({hasText:'重连'}).waitFor();await shot(a.page,'offline');await a.context.setOffline(false);await a.page.locator('#connection').filter({hasText:'已同步'}).waitFor({timeout:15000});await a.page.reload();await a.page.waitForFunction(()=>!!window.__game?.sim.hero());const actual=await a.page.evaluate(()=>({id:__game.sim.player.id,heroId:__game.sim.player.heroId,side:__game.sim.player.side}));assert.deepEqual(actual,before);return {before,actual};});
 await check('640x1136 and mobile 390x844/360x800/320x568: HUD/detail/touch target sizes',async()=>{const a=actors.at(-1);prepare(a,0);await sync();const sizes=[];for(const [width,height] of [[640,1136],[390,844],[360,800],[320,568]]){await a.page.setViewportSize({width,height});await a.page.locator('#locate').click();await a.page.waitForTimeout(350);await shot(a.page,`viewport-${width}x${height}`);const measure=await a.page.evaluate(()=>{const rect=selector=>{const e=document.querySelector(selector),r=e.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height,fontSize:getComputedStyle(e).fontSize,scale:r.width/e.offsetWidth};};return {viewport:[innerWidth,innerHeight],scrollWidth:document.documentElement.scrollWidth,game:rect('.game'),skill:rect('[data-cast="0"]'),info:rect('[data-info="0"]'),cost:rect('.skill-cost'),caption:rect('.skill-caption b'),footer:rect('footer'),hostControlsInside:!!document.querySelector('.game #hostControls')};});assert.ok(measure.scrollWidth<=width);assert.ok(measure.footer.y+measure.footer.height<=height+2);await a.page.locator('[data-info="2"]').click();await a.page.locator('[data-ability-detail="2"] summary').click();await shot(a.page,`detail-${width}x${height}`);await a.page.locator('#sheetClose').click();sizes.push(measure);}return sizes;});
 await check('mobile touch canvas selection and confirm with no preselection',async()=>{const context=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true}),page=await context.newPage();contexts.push(context);page.on('pageerror',e=>out.errors.push({mobile:true,message:e.message}));await page.goto(base);await shot(page,'mobile-login');await page.locator('#accountName').fill('触屏检测'+Date.now());await page.locator('#accountPassword').fill('isolated-audit-only');await page.locator('#authSubmit').tap();await page.waitForFunction(()=>window.__game?.renderer.getCamera());const p=room.player(game.accounts.rows.at(-1));const soldier=s.spawn(0,'ranged',0,1,0);soldier.y=-50;soldier.speed=0;await sync();await page.waitForFunction(id=>!!__game.sim.get(id),soldier.id);await clickUnit(page,soldier.id,true);await page.locator('#contractPopover').waitFor({state:'visible'});await page.locator('[data-contract-role="5"]').tap();await shot(page,'mobile-contract');await page.locator('#confirmContract').tap();await page.waitForFunction(()=>__game.sim.hero()?.classId===5);assert.equal(s.hero(p).classId,5);await shot(page,'mobile-contracted');await context.close();return {heroId:p.heroId,side:p.side};});
 await check('fire->orc->fire preserves independent progress and build',async()=>{const a=actors[2],p=a.p,h=s.hero(p);const before=clone(p.progress[4]),build=clone(p.builds[4]);s.damage(null,h,1e9);let u=s.spawn(0,'melee',0,1,0);u.y=-50;await sync();await a.page.setViewportSize({width:1440,height:1200});await clickUnit(a.page,u.id);await a.page.locator('#confirmContract').click();await a.page.waitForFunction(()=>__game.sim.hero()?.classId===0);assert.equal(p.level,1);s.damage(null,s.hero(p),1e9);u=s.spawn(0,'ranged',0,1,0);u.y=-50;await sync();await clickUnit(a.page,u.id);await a.page.locator('[data-contract-role="4"]').click();await a.page.locator('#confirmContract').click();await a.page.waitForFunction(()=>__game.sim.hero()?.classId===4);assert.deepEqual(p.progress[4],before);assert.deepEqual(p.builds[4],build);return {before,after:p.progress[4],build};});
 await check('two-minute real browser continuous 5-account runtime at 4x with frame and SSE samples',async()=>{
  // Reset ONLY this in-process isolated room for a natural battle following deterministic skill fixtures.
  room.sim.resetMap();room.stageResetAt=s.metrics.resets;for(const p of room.sim.players){if(p.retired)continue;p.stamina=100;p.auto=true;}
  room.paused=false;room.speed=4;for(const a of actors){const u=s.units.find(u=>!u.hero&&u.side===a.p.side&&u.type===contractType(a.classId));if(u){s.setClass(a.classId,a.p);s.contract(a.p,u.id);}}
  for(const t of s.towers)t.x=(t.id%6-2.5)*s.config.tower.spacing;await sync();
  await Promise.all(pages.map(p=>p.evaluate(()=>{window.__auditFrames=[];window.__auditSequences=[];let last=performance.now();window.__auditRaf=0;const frame=now=>{__auditFrames.push(now-last);last=now;if(__auditFrames.length>20000)__auditFrames.shift();__auditRaf=requestAnimationFrame(frame);};__auditRaf=requestAnimationFrame(frame);window.__auditInterval=setInterval(()=>__auditSequences.push({at:performance.now(),sequence:__game.sim.sequence,time:__game.sim._serverTime,units:__game.sim.units.length,connected:__game.network.connected}),200);})));console.log('NATURAL_BROWSER_START');
  const samples=[];for(let i=0;i<12;i++){await pages[0].waitForTimeout(10000);samples.push({wallSeconds:(i+1)*10,time:s.time,units:s.units.length,projectiles:s.projectiles.length,casts:s.metrics.casts,sequence:room.sequence,clients:room.clients.size});if(i===5)console.log('NATURAL_BROWSER_60_SECONDS');}
  const frames=await Promise.all(pages.map(p=>p.evaluate(()=>{cancelAnimationFrame(__auditRaf);clearInterval(__auditInterval);const arr=__auditFrames.filter(x=>x<1000).sort((a,b)=>a-b),seq=__auditSequences;return {frames:arr.length,p50:arr[Math.floor(arr.length*.5)],p95:arr[Math.floor(arr.length*.95)],over50ms:arr.filter(x=>x>50).length,sequenceSamples:seq,gaps:seq.slice(1).map((v,i)=>({ms:v.at-seq[i].at,delta:v.sequence-seq[i].sequence})).filter(x=>x.delta===0)};})));room.paused=true;await sync();await shot(pages[0],'natural-multiplayer');assert.ok(frames.every(f=>f.sequenceSamples.at(-1).sequence>f.sequenceSamples[0].sequence));return {samples,frames};
 });
}catch(e){out.fatal={error:e.message,stack:e.stack};}
finally{fs.writeFileSync(`${dir}/browser-audit.json`,JSON.stringify(out,null,2));await browser.close();for(const c of [...room.clients])c.res.end();game.server.closeAllConnections();await new Promise(r=>game.server.close(r));console.log(JSON.stringify({base,passes:out.checks.filter(x=>x.status==='PASS').length,failures:out.checks.filter(x=>x.status==='FAIL'),fatal:out.fatal,errors:out.errors,networkErrors:out.networkErrors,skills:out.skills.length,screenshots:out.screenshots.length},null,2));}
